Networks fail. Clients retry.
Your system should be ready
for ==both.==

slides.code:
const claim = await db.query(
  `INSERT INTO idempotency_keys (key, status)
   VALUES ($1, 'in_progress')
   ON CONFLICT (key) DO NOTHING
   RETURNING key`, [key]);

if (!claim.rowCount) {
  const prior = await load(key);
  // Winner still running. Nothing to replay yet.
  if (prior.status === 'in_progress')
    return res.status(409);
  return res.status(prior.code).json(prior.body);
}
